#!/usr/bin/env node
// Builds the static site from src/ and site.config.json into the repo root.
//
//   node scripts/build.mjs          write pages
//   node scripts/build.mjs --check  exit 1 if any committed page is out of date
//
// Templates support:
//   {{> partial}}         include src/partials/partial.html
//   {{path.to.value}}     value from site.config.json (HTML-escaped)
//   {{@helper}}           HTML generated by a helper below
// Each page starts with <!--page {"title": "...", "description": "..."} -->.

import { readFileSync, writeFileSync, readdirSync, mkdirSync, existsSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const config = JSON.parse(readFileSync(join(root, "site.config.json"), "utf8"));
const check = process.argv.includes("--check");

const esc = (s) =>
  String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);

function lookup(path, scope) {
  const value = path.split(".").reduce((obj, key) => (obj == null ? undefined : obj[key]), scope);
  if (value === undefined) throw new Error(`Unknown template value: {{${path}}}`);
  return value;
}

const NAV = [
  { href: "/competition/", label: "Competition" },
  { href: "/programs/", label: "Programs" },
  { href: "/toolkit/", label: "Toolkit" },
  { href: "/about/", label: "About" },
  { href: "/get-involved/", label: "Get involved" },
];

const helpers = {
  nav: (page) =>
    NAV.map(
      (n) =>
        `<li><a href="${n.href}"${page.url.startsWith(n.href) ? ' aria-current="page"' : ""}>${esc(n.label)}</a></li>`
    ).join(""),

  route: () =>
    `<ol class="route">${config.stages
      .map(
        (s) => `
      <li class="route-${s.kind}">
        <div class="post" aria-hidden="true"><small>${s.kind === "mile" || s.kind === "check" ? "MILE" : s.kind === "gate" ? "GATE" : "FINAL"}</small><b>${s.kind === "mile" || s.kind === "check" ? esc(s.key) : s.kind === "gate" ? "✓" : "★"}</b></div>
        <div class="route-body">
          <p class="route-meta"><span>${esc(s.dates)}</span><span>${esc(s.who)}</span></p>
          <h3>${s.kind === "mile" || s.kind === "check" ? `${esc(s.label)}: ` : ""}${esc(s.name)}${s.kind === "final" ? ` at ${esc(config.final.venue)}` : ""}</h3>
          <p>${esc(s.summary)}</p>
          ${s.submit.length ? `<p class="submit"><span>Submit</span> ${s.submit.map(esc).join(" · ")}</p>` : ""}
        </div>
      </li>`
      )
      .join("")}
    </ol>`,

  routeCompact: () =>
    `<ol class="route-compact">${config.stages
      .map(
        (s) =>
          `<li class="route-${s.kind}"><span class="rc-date">${esc(s.dates)}</span><span class="rc-name">${s.kind === "mile" || s.kind === "check" ? `<b>${esc(s.label)}</b> ` : ""}${esc(s.name)}</span></li>`
      )
      .join("")}</ol>`,

  criteria: () =>
    `<dl class="criteria">${config.criteria
      .map((c) => `<div><dt>${esc(c.name)}</dt><dd>${esc(c.question)}</dd></div>`)
      .join("")}</dl>`,

  weights: () => `
    <div class="table-scroll"><table class="weights">
      <caption>Weighting of each criterion by stage. Mile 0 is auto-marked and not weighted.</caption>
      <thead><tr><th scope="col">Stage</th>${config.criteria.map((c) => `<th scope="col">${esc(c.short)}</th>`).join("")}</tr></thead>
      <tbody>${config.weights
        .map((w) => {
          const max = Math.max(...w.values);
          return `<tr><th scope="row">${esc(w.stage)}</th>${w.values
            .map((v) => `<td${v === max && w.values.filter((x) => x === max).length === 1 ? ' class="peak"' : ""}>${v}%</td>`)
            .join("")}</tr>`;
        })
        .join("")}</tbody>
    </table></div>`,

  // Only partners whose logo use has been approved in writing appear publicly.
  partnerBar: () => {
    const shown = config.partners.filter((p) => p.logoApproved);
    if (!shown.length) return "";
    return `
    <section class="partners" aria-labelledby="partners-h">
      <div class="wrap">
        <h2 id="partners-h" class="label">Supported by</h2>
        <ul class="partner-list">${shown
          .map(
            (p) =>
              `<li>${p.logo ? `<img src="${esc(p.logo)}" alt="${esc(p.name)}" loading="lazy">` : `<span class="wordmark">${esc(p.name)}</span>`}<small>${esc(p.role)}</small></li>`
          )
          .join("")}</ul>
      </div>
    </section>`;
  },

  // Students are only named once they have agreed to it.
  team: () => {
    const shown = config.team.filter((t) => t.consent);
    if (!shown.length) return `<p class="muted">Team profiles are coming soon.</p>`;
    return `<ul class="team">${shown
      .map((t) => `<li><b>${esc(t.name)}</b><span>${esc(t.role)}</span><small>${esc(t.school)}</small></li>`)
      .join("")}</ul>`;
  },

  instagram: () =>
    config.brand.instagram
      ? `<li><a href="https://instagram.com/${esc(config.brand.instagram)}" rel="noopener">Instagram</a></li>`
      : "",

  // The rendered page body, for the layout partial.
  content: (page) => page.body,
};

function render(template, page, depth = 0) {
  if (depth > 5) throw new Error("Partials nested too deeply");
  return template
    .replace(/\{\{>\s*([\w-]+)\s*\}\}/g, (_, name) =>
      render(readFileSync(join(root, "src/partials", `${name}.html`), "utf8"), page, depth + 1)
    )
    .replace(/\{\{@(\w+)\}\}/g, (_, name) => {
      if (!helpers[name]) throw new Error(`Unknown helper: {{@${name}}}`);
      return helpers[name](page);
    })
    .replace(/\{\{\s*([\w.]+)\s*\}\}/g, (_, path) => esc(lookup(path, { ...config, page })));
}

const pagesDir = join(root, "src/pages");
let stale = 0;
for (const file of readdirSync(pagesDir).filter((f) => f.endsWith(".html"))) {
  const source = readFileSync(join(pagesDir, file), "utf8");
  const match = source.match(/^<!--page\s+(\{[\s\S]*?\})\s*-->\n?/);
  if (!match) throw new Error(`${file}: missing <!--page {...} --> header`);
  const slug = file.replace(/\.html$/, "");
  const url = slug === "index" ? "/" : slug === "404" ? "/404.html" : `/${slug}/`;
  const out = slug === "index" || slug === "404" ? `${slug}.html` : `${slug}/index.html`;
  const meta = JSON.parse(match[1].replace(/\{\{\s*([\w.]+)\s*\}\}/g, (_, path) => lookup(path, config)));
  const page = { ...meta, url, slug };
  page.fullTitle = slug === "index" ? `${config.brand.name}: ${config.brand.tagline}` : `${page.title} · ${config.brand.name}`;

  page.body = render(source.slice(match[0].length), page);
  const html = render(readFileSync(join(root, "src/partials/layout.html"), "utf8"), page);

  const target = join(root, out);
  if (check) {
    if (!existsSync(target) || readFileSync(target, "utf8") !== html) {
      console.error(`stale: ${relative(root, target)}`);
      stale++;
    }
  } else {
    mkdirSync(dirname(target), { recursive: true });
    writeFileSync(target, html);
    console.log(`built ${out}`);
  }
}

if (check && stale) {
  console.error(`\n${stale} page(s) out of date. Run: node scripts/build.mjs`);
  process.exit(1);
}
